-- Run only through a trusted database connection, replacing the UUID after verifying auth.users.
create function public.bootstrap_first_admin(target_user uuid) returns void language plpgsql security definer set search_path='' as $$begin if exists(select 1 from public.staff_roles) then raise exception 'staff already exists';end if;if not exists(select 1 from auth.users where id=target_user) then raise exception 'auth user not found';end if;insert into public.staff_roles(user_id,role,granted_by) values(target_user,'ADMIN',target_user);insert into public.audit_events(actor_id,action,object_type,object_id,reason)values(target_user,'FIRST_ADMIN_BOOTSTRAPPED','user',target_user,'trusted database bootstrap');end$$;revoke all on function public.bootstrap_first_admin(uuid) from public,anon,authenticated;
